#include "../../SRC/Server/GameServer/social/SocialHistoryCrypto.hpp"
#include <stdexcept>
#include <iostream>
int main(){using namespace auriga::social::history;auto check=[](bool value){if(!value)throw std::runtime_error("Social history authentication");};Key key{};Metadata m{1,1800000000000,10,20,10,1,1,0,"Eva"};auto sealed=Seal(key,m,"Eva : Secret message");check(sealed.has_value());check(Open(key,m,*sealed)=="Eva : Secret message");auto other=Seal(key,m,"Eva : Secret message");check(other&&other->nonce!=sealed->nonce);auto wrong=key;wrong[0]=1;check(!Open(wrong,m,*sealed));auto altered=*sealed;altered.cipher[0]^=1;check(!Open(key,m,altered));altered=*sealed;altered.tag[0]^=1;check(!Open(key,m,altered));altered=*sealed;altered.nonce[0]^=1;check(!Open(key,m,altered));for(int field=0;field<7;field++){auto changed=m;switch(field){case 0:changed.id++;break;case 1:changed.created++;break;case 2:changed.sender=20;break;case 3:changed.b++;break;case 4:changed.name="Other";break;case 5:changed.empire=2;break;case 6:changed.gm=1;break;}check(!Open(key,changed,*sealed));}check(!Seal(key,m,std::string(1025,'a')));check(!Seal(key,m,""));check(Unhex(Hex(std::string("\0\xff",2)))==std::string("\0\xff",2));check(!Unhex("x1"));check(!Unhex("123"));std::cout<<"SOCIAL_HISTORY_CRYPTO=PASS confidentiality authentication metadata nonce bounds\n";}
